		[TestDate(2011, 01, 20, 15, 39, 42)]
		public void TestPLAppropriationAccount_BranchFilter()
		{
			var existingPeriods = new AccPeriodManagementCollection(Factory);
			existingPeriods.Load();
			existingPeriods.RemoveAndDeleteAll();
			var transactionCreator = new TestBulkTransactionCreator(Factory, TestObjectCreator, true);
			transactionCreator.Setup();
			Factory.LoadTop1<AccChargeCode>(new ZQuery(AccChargeCodeSchema.AC_Code, "BOND")).Delete();
			Factory.LoadTop1<AccChargeCode>(new ZQuery(AccChargeCodeSchema.AC_Code, "CLAIM")).Delete();
			Factory.Save();

			TestObjectCreator.GLHeader1.AG_AccountType = Core.Constants.AccountType.ProfitAndLossAccount;
			var inv1 = TestObjectCreator.CreateInvoiceWithLine(typeof(APInvoice), "INV1", TestObjectCreator.AUD, 1M, 10, 0M, 10, 0M, TestObjectCreator.ABIGAS, TestObjectCreator.GLHeader1.PK, new ZDateTime(2010, 1, 1), ZDateTime.Empty, new ZDateTime(2010, 1, 1), false);
			var inv2 = TestObjectCreator.CreateInvoiceWithLine(typeof(APInvoice), "INV2", TestObjectCreator.AUD, 1M, 20, 0M, 20, 0M, TestObjectCreator.ABIGAS, TestObjectCreator.GLHeader1.PK, new ZDateTime(2010, 1, 1), ZDateTime.Empty, new ZDateTime(2010, 1, 1), false);
			inv1.AH_GB = TestObjectCreator.NonCurrentBranch.PK;
			inv1.Lines[0].AL_GB = TestObjectCreator.NonCurrentBranch.PK;
			Factory.Save();

			Db.Connection.ExecuteNonQuery(string.Format("EXEC TakeUpSubledgers '{0}', 'TST'", GlbCompany.CurrentCompany.PK));

			var plAppropriationAccount = Factory.Load<AccGLHeader>((Guid)AccountingConfigurationRegistry.Instance.PLAppropriationAccount.Value);
			var fullDateTimeColumns = new[] { "OpeningPeriodDate", "ClosingPeriodDate" };
			var pkReplacment = new List<Tuple<ZGuid, string>>();
			var expectedResult = @"
PK                                   TransactionType InvoiceDate             PostDate                DueDate                 Branch Department Ledger TransactionNum       SecondRef                           TransactionDesc                                                                                                                  GLAccount    GLAccountDesc                       Units                Job                                                Account      ChargeCode ChargeCodeDescription                                                            LocalLanguageChargeCodeDescription                                                                                                                               Period      ReversePeriod Amount                GSTAmount             Debit                 Credit                Balance               IsLine TRPK                                 OpeningPeriodDate       ClosingPeriodDate       OpeningBalance        ClosingBalance        IsControlTotal IsRevenueRecognition BatchNumber BatchType SubSelectID ParentTableCode PKFORBATCHING                        OsAmount              ExRate                Currency OsDebit               OsCredit              OsExTaxDebit          OsExTaxCredit         MultiSubAccountTypeCode OrganisationSubAccount  SalesExpenseGroupsSubAccount StaffAndResourcesSubAccount StaffGroupSubAccount ComplianceSubType ComplianceNumber     JournalEntriesNumber
------------------------------------ --------------- ----------------------- ----------------------- ----------------------- ------ ---------- ------ -------------------- ----------------------------------- -------------------------------------------------------------------------------------------------------------------------------- ------------ ----------------------------------- -------------------- -------------------------------------------------- ------------ ---------- -------------------------------------------------------------------------------- ---------------------------------------------------------------------------------------------------------------------------------------------------------------- ----------- ------------- --------------------- --------------------- --------------------- --------------------- --------------------- ------ ------------------------------------ ----------------------- ----------------------- --------------------- --------------------- -------------- -------------------- ----------- --------- ----------- --------------- ------------------------------------ --------------------- --------------------- -------- --------------------- --------------------- --------------------- --------------------- ----------------------- ----------------------- ---------------------------- --------------------------- -------------------- ----------------- -------------------- --------------------
NULL                                 NULL            NULL                    NULL                    NULL                    NULL   NULL       NULL   NULL                 NULL                                NULL                                                                                                                             4900.00.00   RETAINED EARNINGS FROM PREVIOUS YR  NULL                 NULL                                               NULL         NULL       NULL                                                                             NULL                                                                                                                                                             NULL        NULL          0.00                  0.00                  NULL                  NULL                  0.00                  0      NULL                                 2011-01-01 00:00:00.000 2011-01-31 23:59:00.000 BalanceAmount         BalanceAmount         0              0                    NULL        NULL      NULL        NULL            NULL                                 0.00                  1.00                  AUD      NULL                  NULL                  NULL                  NULL                  NULL                    NULL                    NULL                         NULL                        NULL                 NULL              NULL
";

			var resultTable = RunScript(201101, 201101, GlbCompany.CurrentCompany.PK, plAppropriationAccount.PK, plAppropriationAccount.PK);
			AssertTableAsTextFromSQLServerManagenentStudio("Branch Filter: null", resultTable, expectedResult.Replace("BalanceAmount", "30.00"), fullDateTimeColumns, pkReplacment);

			resultTable = RunScript(201101, 201101, GlbCompany.CurrentCompany.PK, plAppropriationAccount.PK, plAppropriationAccount.PK, TestObjectCreator.NonCurrentBranch.PK);
			AssertTableAsTextFromSQLServerManagenentStudio("Branch Filter: NonCurrentBranch", resultTable, expectedResult.Replace("BalanceAmount", "10.00"), fullDateTimeColumns, pkReplacment);

			resultTable = RunScript(201101, 201101, GlbCompany.CurrentCompany.PK, plAppropriationAccount.PK, plAppropriationAccount.PK, GlbBranch.CurrentBranch.PK);
			AssertTableAsTextFromSQLServerManagenentStudio("Branch Filter: CurrentBranch", resultTable, expectedResult.Replace("BalanceAmount", "20.00"), fullDateTimeColumns, pkReplacment);
		}

