			var plAppropriationAccount = Factory.Load<AccGLHeader>((Guid)AccountingConfigurationRegistry.Instance.PLAppropriationAccount.Value);
			TestObjectCreator.GLHeader1.AG_AccountType = Core.Constants.AccountType.ProfitAndLossAccount;

