			inv2.Lines[0].AL_GB = TestObjectCreator.NonCurrentBranch.PK;

			var inv3 = TestObjectCreator.CreateInvoiceWithLine(typeof(APInvoice), "INV3", TestObjectCreator.AUD, 1M, 30, 0M, 30, 0M, TestObjectCreator.ABIGAS, TestObjectCreator.GLHeader1.PK, new ZDateTime(2010, 1, 1), ZDateTime.Empty, new ZDateTime(2010, 1, 1), false);
			inv3.AH_GE = TestObjectCreator.NonCurrentDepartment.PK;
			inv3.Lines[0].AL_GE = TestObjectCreator.NonCurrentDepartment.PK;

			var inv4 = TestObjectCreator.CreateInvoiceWithLine(typeof(APInvoice), "INV4", TestObjectCreator.AUD, 1M, 70, 0M, 70, 0M, TestObjectCreator.ABIGAS, TestObjectCreator.GLHeader1.PK, new ZDateTime(2010, 1, 1), ZDateTime.Empty, new ZDateTime(2010, 1, 1), false);
