		#endregion

		void AssertCashBasisVATAmountSigns(Type invoiceType, string expectedResult, bool useVATRecoverable = false)
		{
			setupCommonData();

			var invoice = TestObjectCreator.CreateInvoiceWithCashVATLine(invoiceType, 100, 10, departmentCode: "FIP");
			invoice.AH_PostToGL = "Y";
			invoice.AH_ComplianceSubType = "ABC";
			invoice.AH_TransactionReference = "ABC00123";
			invoice.AH_TransactionNum = "Export Test";
			var matchDate = invoice.AH_PostDate.AddDays(3);

			if ((invoice.AH_Ledger == "AP" && invoice.AH_TransactionType != "CRD") || (invoice.AH_Ledger == "AR" && invoice.AH_TransactionType == "CRD"))
			{
				TestObjectCreator.CreateMatchLinkToPayAPInvoice(invoice, matchDate, -40);
			}
			else
			{
				TestObjectCreator.CreateMatchLinkToPayARInvoice(invoice, matchDate, 40);
			}

			var line = invoice.Lines[0];
			if (useVATRecoverable)
			{
				line.AL_InputGSTVATRecoverable = 0.7777m;
			}
			Factory.Save();
			AssertEquals("Precondition: line1 AL_GSTVATBasis", AccountingMasterFilesConstants.TransactionLineTaxBasisTypes.Cash.Code, line.AL_GSTVATBasis);

			TestConnection.ExecuteNonQuery("DELETE FROM dbo.AccCashBasisVATQueue");
			var resultTable = RunScript(invoice.AH_PostDate, matchDate);
			var fullDateTimeColumns = new[] { "OpeningPeriodDate", "ClosingPeriodDate" };
			var cashVAT = Factory.LoadTop1<AccCashBasisVAT>(new ZQuery(AccCashBasisVATSchema.YC_AL_TransactionLine, line.PK));
			var pkReplacment = new List<Tuple<ZGuid, string>>(new[] { new Tuple<ZGuid, string>(line.PK, "LinePK"), new Tuple<ZGuid, string>(cashVAT.PK, "CashVATPK") });
			AssertTableAsTextFromSQLServerManagenentStudio(invoiceType.Name, resultTable, expectedResult, fullDateTimeColumns, pkReplacment);
		}

