		[TestDate(2023, 05, 04)]
		[SuspendCriticalValidation]
		public void TestARTaxTransactionsFilterBySpecificGLAccount()
		{
			try
			{
				setupCommonData();

				var invoice = TestObjectCreator.CreateInvoice(typeof(ARInvoice), "Export Test", TestObjectCreator.AUD, 1, TestObjectCreator.Debtor);
				invoice.AH_PostDate = ZDateTime.Today.AddDays(-30);
				var taxTransaction1 = TaxFrameworkTestHelper.CreateTaxTransaction(new CreateTaxTransactionParameters { CompanyPK = GlbCompany.CurrentCompany.PK, TransactionHeaderPK = invoice.PK, OsTaxAmount = 12M, Ledger = TaxConfigurationLedgers.AccountsReceivable.Code, DoesNotCreateGLMovemetsOnSaving = true });
				var taxTransaction2 = TaxFrameworkTestHelper.CreateTaxTransaction(new CreateTaxTransactionParameters { CompanyPK = GlbCompany.CurrentCompany.PK, TransactionHeaderPK = invoice.PK, OsTaxAmount = 24M, Ledger = TaxConfigurationLedgers.AccountsReceivable.Code, DoesNotCreateGLMovemetsOnSaving = true });
				var taxTransaction3 = TaxFrameworkTestHelper.CreateTaxTransaction(new CreateTaxTransactionParameters { CompanyPK = GlbCompany.CurrentCompany.PK, TransactionHeaderPK = invoice.PK, OsTaxAmount = 36M, Ledger = TaxConfigurationLedgers.AccountsReceivable.Code, DoesNotCreateGLMovemetsOnSaving = true });

				var period = new ZInt("202401");
				var postdate = ZDateTime.Today;
				var matchdate = ZDateTime.Today.AddDays(2);
				var glMovement1 = TaxFrameworkTestHelper.CreateAccTaxGLMovement(taxTransaction1.PK, ARControlAccount.PK, TaxControlAccount.PK, 10M, period, postdate.Date);
				var glMovement2 = TaxFrameworkTestHelper.CreateAccTaxGLMovement(taxTransaction2.PK, TaxControlAccount.PK, ARControlAccount.PK, 20M, period, matchdate.Date);
				var glMovement3 = TaxFrameworkTestHelper.CreateAccTaxGLMovement(taxTransaction3.PK, ARControlAccount.PK, PendingTaxControlAccount.PK, 30M, period, postdate.Date, TaxGLMovementTypeList.Pending.Code);
				var glMovement4 = TaxFrameworkTestHelper.CreateAccTaxGLMovement(taxTransaction3.PK, PendingTaxControlAccount.PK, TaxControlAccount.PK, 30M, period, postdate.Date, TaxGLMovementTypeList.Realised.Code);
				Factory.Save();

				var fullDateTimeColumns = new[] { "OpeningPeriodDate", "ClosingPeriodDate" };
				var pkReplacment = new List<Tuple<ZGuid, string>>(new[] { new Tuple<ZGuid, string>(glMovement1.PK, "glMovement1PK"), new Tuple<ZGuid, string>(glMovement2.PK, "glMovement2PK")
