		[TestDate(2006, 06, 20, 15, 39, 42)]
		[SuspendCriticalValidation]
		public void TestTF_BranchDepartmentFilterForARTaxTransactions()
		{
			setupCommonData();

			var branch1 = TestObjectCreator.CreateBranch("BR1", GlbCompany.CurrentCompany);
			var branch2 = TestObjectCreator.CreateBranch("BR2", GlbCompany.CurrentCompany);
			var department1 = TestObjectCreator.CreateDepartment("D1");
			var department2 = TestObjectCreator.CreateDepartment("D2");

			var invoice = TestObjectCreator.CreateInvoice(typeof(ARInvoice), "Export Test", TestObjectCreator.AUD, 1, TestObjectCreator.Debtor);
			invoice.AH_PostDate = ZDateTime.Today.AddDays(-30);
			invoice.AH_ComplianceSubType = "ABC";
			invoice.AH_TransactionReference = "ABC00123";

			var taxTransaction1 = TaxFrameworkTestHelper.CreateTaxTransaction(new CreateTaxTransactionParameters { CompanyPK = GlbCompany.CurrentCompany.PK, TransactionHeaderPK = invoice.PK, OsTaxAmount = 12M, Ledger = TaxConfigurationLedgers.AccountsReceivable.Code, DoesNotCreateGLMovemetsOnSaving = true });
			taxTransaction1.ATT_GB = branch1.PK;
			taxTransaction1.ATT_GE_Department = department1.PK;

			var taxTransaction2 = TaxFrameworkTestHelper.CreateTaxTransaction(new CreateTaxTransactionParameters { CompanyPK = GlbCompany.CurrentCompany.PK, TransactionHeaderPK = invoice.PK, OsTaxAmount = 24M, Ledger = TaxConfigurationLedgers.AccountsReceivable.Code, DoesNotCreateGLMovemetsOnSaving = true });
			taxTransaction2.ATT_GB = branch1.PK;
			taxTransaction2.ATT_GE_Department = department2.PK;

			var taxTransaction3 = TaxFrameworkTestHelper.CreateTaxTransaction(new CreateTaxTransactionParameters { CompanyPK = GlbCompany.CurrentCompany.PK, TransactionHeaderPK = invoice.PK, OsTaxAmount = 36M, Ledger = TaxConfigurationLedgers.AccountsReceivable.Code, DoesNotCreateGLMovemetsOnSaving = true });
			taxTransaction3.ATT_GB = branch2.PK;
			taxTransaction3.ATT_GE_Department = department2.PK;

			var period = new ZInt("200701");
			var postdate = ZDate.Today;
			var matchdate = ZDate.Today.AddDays(2);
			var glMovement1 = TaxFrameworkTestHelper.CreateAccTaxGLMovement(taxTransaction1.PK, ARControlAccount.PK, TaxControlAccount.PK, 10M, period, postdate);
			var glMovement2 = TaxFrameworkTestHelper.CreateAccTaxGLMovement(taxTransaction2.PK, TaxControlAccount.PK, ARControlAccount.PK, 20M, period, matchdate);
			var glMovement3 = TaxFrameworkTestHelper.CreateAccTaxGLMovement(taxTransaction3.PK, ARControlAccount.PK, PendingTaxControlAccount.PK, 30M, period, postdate, TaxGLMovementTypeList.Pending.Code);
			var glMovement4 = TaxFrameworkTestHelper.CreateAccTaxGLMovement(taxTransaction3.PK, PendingTaxControlAccount.PK, TaxControlAccount.PK, 30M, period, postdate, TaxGLMovementTypeList.Realised.Code);

			var firstGLAccount = Factory.LoadFromUniqueKey<AccGLHeader>(AccGLHeaderSchema.AG_AccountNum, new ZString("1000.00.00")).PK;
			var lastGLAccount = Factory.LoadFromUniqueKey<AccGLHeader>(AccGLHeaderSchema.AG_AccountNum, new ZString("9999.00.00")).PK;

			Factory.Save();

