		void CreateLocalGLMapping(ZGuid glAccountPK, ZString localGLAccountNum, Guid localGLAccountPK)
		{
			TestConnection.ExecuteNonQuery($@"INSERT INTO dbo.AccGLAccountDescriptor(AJ_PK, AJ_Language, AJ_AccountDescription, AJ_LocalAccountNumber, AJ_ReportType, AJ_DebitCredit, AJ_RN_NKCountryOfCompliance, AJ_SystemCreateTimeUtc, AJ_SystemCreateUser, AJ_SystemLastEditTimeUtc, AJ_SystemLastEditUser) 
VALUES('{localGLAccountPK}', 'ZH-CN', '12340100', '{localGLAccountNum}', 'COA', 'CR', 'CN', GetUtcDate(), '~BP', GetUtcDate(), '~BP')");

			TestConnection.ExecuteNonQuery($@"INSERT INTO dbo.AccGLDescriptorPivot (YJ_PK, YJ_AG, YJ_AJ, YJ_SystemCreateTimeUtc, YJ_SystemCreateUser, YJ_SystemLastEditTimeUtc, YJ_SystemLastEditUser) values (NEWID(), '{glAccountPK}', '{localGLAccountPK}', GetUtcDate(), '~BP', GetUtcDate(), '~BP')");
		}

