		[TestDate(2006, 06, 20, 23, 59, 01)]
		public void TestOpeningBalance()
		{
			setupCommonData();
			TestObjectCreator.CreateTestPeriods(new ZDateTime(2006, 1, 1));

			var invoice = TestObjectCreator.CreateInvoiceWithCashVATLine(typeof(APInvoice), 100m, 10m, departmentCode: "FIP");
			TestObjectCreator.CreateInvoiceLine(invoice, TestObjectCreator.AUD, 1m, 50m, 5m, 0m, TestObjectCreator.GLHeader1.PK);
			invoice.AH_PostToGL = "Y";
			invoice.AH_TransactionNum = "Opening Bal Test";
			invoice.AH_ComplianceSubType = "ABC";
			invoice.AH_TransactionReference = "ABC00123";
			var line1 = invoice.Lines[0];
			var line2 = invoice.Lines[1];
			line1.AL_InputGSTVATRecoverable = 0.8m;
			line2.AL_InputGSTVATRecoverable = 0.3m;
			line1.AL_ReverseToGL = "Y";
			line2.AL_ReverseToGL = "Y";

			var prevInvoice = TestObjectCreator.CreateInvoiceWithCashVATLine(typeof(APInvoice), 10m, 0m, departmentCode: "FIP");
			prevInvoice.AH_InvoiceDate = ZDateTime.Today.AddDays(-10);
			prevInvoice.AH_PostDate = prevInvoice.AH_InvoiceDate;
			TestObjectCreator.CreateInvoiceLine(prevInvoice, TestObjectCreator.AUD, 1m, 10m, 0m, 0m, TestObjectCreator.GLHeader1.PK);
			prevInvoice.AH_PostToGL = "Y";
			prevInvoice.AH_TransactionNum = "Opening Bal B4 RDate";
			var prevLine1 = prevInvoice.Lines[0];
			var prevLine2 = prevInvoice.Lines[1];
			prevLine1.AL_ReverseToGL = "Y";
			prevLine2.AL_ReverseToGL = "Y";

			TestObjectCreator.GLHeader1.AG_AccountType = "P&L"; // We need to set P&L type to reproduce issue with 0 opening Balance on GLHeader1
			Factory.Save();

			AssertEquals("Precondition: line1 AL_GSTVATBasis", AccountingMasterFilesConstants.TransactionLineTaxBasisTypes.Cash.Code, line1.AL_GSTVATBasis);
			AssertEquals("Precondition: line2 AL_GSTVATBasis", AccountingMasterFilesConstants.TransactionLineTaxBasisTypes.Accrual.Code, line2.AL_GSTVATBasis);
			TestConnection.ExecuteNonQuery("DELETE FROM dbo.AccCashBasisVATQueue");

			var resultTable = RunScript(invoice.AH_PostDate, invoice.AH_PostDate);
			var expectedResult = @"
