		[TestDate(2008, 6, 15)]
		[SuspendCriticalValidation]
		public void TestUnrelatedExportsDoNotAffectResults()
		{
			var existingPeriods = new AccPeriodManagementCollection(Factory);
			existingPeriods.Load();
			existingPeriods.RemoveAndDeleteAll();

			var transactionCreator = new TestBulkTransactionCreator(Factory, TestObjectCreator, true);
			transactionCreator.Setup();
			transactionCreator.CreateTransactions();
			Factory.Save();

			Factory.LoadTop1<AccChargeCode>(new ZQuery(AccChargeCodeSchema.AC_Code, "BOND")).Delete();
			Factory.LoadTop1<AccChargeCode>(new ZQuery(AccChargeCodeSchema.AC_Code, "CLAIM")).Delete();
			Factory.Save();

			Db.Connection.ExecuteNonQuery(string.Format("EXEC TakeUpSubledgers '{0}', 'TST'", GlbCompany.CurrentCompany.PK));

			var firstGLAccount = Factory.LoadFromUniqueKey<AccGLHeader>(AccGLHeaderSchema.AG_AccountNum, new ZString("1000.00.00")).PK;
			var lastGLAccount = Factory.LoadFromUniqueKey<AccGLHeader>(AccGLHeaderSchema.AG_AccountNum, new ZString("9999.00.00")).PK;

			var before2008 = RunScript(200801, 200812, GlbCompany.CurrentCompany.PK, firstGLAccount, lastGLAccount).Rows.Count;
			var before2009 = RunScript(200901, 200912, GlbCompany.CurrentCompany.PK, firstGLAccount, lastGLAccount).Rows.Count;
			var before2010 = RunScript(201001, 201012, GlbCompany.CurrentCompany.PK, firstGLAccount, lastGLAccount).Rows.Count;
			var before2011 = RunScript(201101, 201112, GlbCompany.CurrentCompany.PK, firstGLAccount, lastGLAccount).Rows.Count;

			CombineAssertions(delegate
			{
				AssertNotEquals("Precondition: there should be some rows in the report for 2008", 0, before2008);
				AssertNotEquals("Precondition: there should be some rows in the report for 2009", 0, before2009);
				AssertNotEquals("Precondition: there should be some rows in the report for 2010", 0, before2010);
				AssertNotEquals("Precondition: there should be some rows in the report for 2011", 0, before2011);
			});

			var group = Factory.New<AccConsolidationGroup>();
			group.YR_Code = "XYZ";
			group.GroupMembers.AddNew().YM_GC_Company = GlbCompany.CurrentCompany.PK;
			Factory.Save();

			new ConsolidationBatchCreator(group.PK).ReadDataAndCreateBatches(); // Create Batches for GL Consolidations
			DuplicateGenExportBatchSequenceRecords(); // simulate what happens when the same transaction is exported for different exports. 
													  // Basically you end up with multiple genexportbatchrecords for the same PK.

			var after2008 = RunScript(200801, 200812, GlbCompany.CurrentCompany.PK, firstGLAccount, lastGLAccount).Rows.Count;
			var after2009 = RunScript(200901, 200912, GlbCompany.CurrentCompany.PK, firstGLAccount, lastGLAccount).Rows.Count;
			var after2010 = RunScript(201001, 201012, GlbCompany.CurrentCompany.PK, firstGLAccount, lastGLAccount).Rows.Count;
			var after2011 = RunScript(201101, 201112, GlbCompany.CurrentCompany.PK, firstGLAccount, lastGLAccount).Rows.Count;

			CombineAssertions(delegate
			{
				AssertEquals("Report should show the same rows before and after running GL Consolidations for 2008 year", before2008, after2008);
				AssertEquals("Report should show the same rows before and after running GL Consolidations for 2009 year", before2009, after2009);
				AssertEquals("Report should show the same rows before and after running GL Consolidations for 2010 year", before2010, after2010);
				AssertEquals("Report should show the same rows before and after running GL Consolidations for 2011 year", before2011, after2011);
			});
		}

		[TestDate(2020, 03, 23, 16, 38, 41)]
		public void TestMultiSubAccounts()
		{
			setupCommonData();

			AccGLHeader glAccount = TestObjectCreator.GLHeader1;
			var salesGroup = TestObjectCreator.CreateSalesGroup("SG1");
			var staffGroup = TestObjectCreator.CreateStaffGroup("STF");
			var staff = GlbStaff.CurrentUser;
			ScriptTestHelper.CreateMultiSubAccounts(TestObjectCreator, AccGLHeaderSubAccountSchema.Constants.TableName, glAccount.PK, OrgHeaderSchema.Constants.Prefix, TestObjectCreator.LocalClient.PK);
			Factory.Save();

			var arInvoice = TestObjectCreator.CreateInvoice(typeof(ARInvoice), "ARINV1", TestObjectCreator.AUD, 1, TestObjectCreator.ABIGAS);
			arInvoice.AH_PostToGL = "Y";
			var line = TestObjectCreator.CreateInvoiceLine(arInvoice, TestObjectCreator.AUD, 1, 10, 0, 0, glAccount.PK);
			line.AL_ReverseToGL = "Y";
			ScriptTestHelper.CreateMultiSubAccounts(TestObjectCreator, AccTransactionLineSubAccountSchema.Constants.TableName, line.PK, OrgHeaderSchema.Constants.Prefix, TestObjectCreator.LocalClient.PK);
			ScriptTestHelper.CreateMultiSubAccounts(TestObjectCreator, AccTransactionLineSubAccountSchema.Constants.TableName, line.PK, AccGroupsSchema.Constants.Prefix, salesGroup.PK);
			Factory.Save();

			var arCreditNote = TestObjectCreator.CreateInvoice(typeof(ARCreditNote), "ARCRD1", TestObjectCreator.AUD, 1, TestObjectCreator.ABIGAS);
			arCreditNote.AH_PostToGL = "Y";
			line = TestObjectCreator.CreateInvoiceLine(arCreditNote, TestObjectCreator.AUD, 1, 10, 0, 0, TestObjectCreator.GLHeader2.PK);
			line.AL_ReverseToGL = "Y";
			Factory.Save();

			var apInvoice = TestObjectCreator.CreateInvoice(typeof(APInvoice), "APINV1", TestObjectCreator.AUD, 1, TestObjectCreator.AALSHI);
			apInvoice.AH_PostToGL = "Y";
			line = TestObjectCreator.CreateInvoiceLine(apInvoice, TestObjectCreator.AUD, 1, 10, 0, 0, glAccount.PK);
			line.AL_ReverseToGL = "Y";
			var job = TestObjectCreator.CreateJobHeader();
			line.AL_JH = job.PK;
			TestObjectCreator.CreateJobCharge(line, job, TestObjectCreator.CC1);
			ScriptTestHelper.CreateMultiSubAccounts(TestObjectCreator, AccTransactionLineSubAccountSchema.Constants.TableName, line.PK, AccGroupsSchema.Constants.Prefix, salesGroup.PK);
			ScriptTestHelper.CreateMultiSubAccounts(TestObjectCreator, AccTransactionLineSubAccountSchema.Constants.TableName, line.PK, GlbStaffSchema.Constants.Prefix, staff.PK);
			ScriptTestHelper.CreateMultiSubAccounts(TestObjectCreator, AccTransactionLineSubAccountSchema.Constants.TableName, line.PK, GlbGroupSchema.Constants.Prefix, staffGroup.PK);
			Factory.Save();

			var apCreditNote = TestObjectCreator.CreateInvoice(typeof(APCreditNote), "APCRD1", TestObjectCreator.AUD, 1, TestObjectCreator.ABIGAS);
			apCreditNote.AH_PostToGL = "Y";
			line = TestObjectCreator.CreateInvoiceLine(apCreditNote, TestObjectCreator.AUD, 1, 10, 0, 0, glAccount.PK);
			line.AL_ReverseToGL = "Y";
			ScriptTestHelper.CreateMultiSubAccounts(TestObjectCreator, AccTransactionLineSubAccountSchema.Constants.TableName, line.PK, OrgHeaderSchema.Constants.Prefix, TestObjectCreator.LocalClient.PK);
			ScriptTestHelper.CreateMultiSubAccounts(TestObjectCreator, AccTransactionLineSubAccountSchema.Constants.TableName, line.PK, AccGroupsSchema.Constants.Prefix, salesGroup.PK);
			ScriptTestHelper.CreateMultiSubAccounts(TestObjectCreator, AccTransactionLineSubAccountSchema.Constants.TableName, line.PK, GlbGroupSchema.Constants.Prefix, staffGroup.PK);
			Factory.Save();

			var aRJournal = TestObjectCreator.CreateJournal<ARJournal>(100m, arInvoice.AH_PostDate, TestObjectCreator.ABIGAS.PK);
			aRJournal.AH_AG = glAccount.PK;
			aRJournal.AH_PostToGL = "Y";
			ScriptTestHelper.CreateMultiSubAccounts(TestObjectCreator, AccTransactionHeaderSubAccountSchema.Constants.TableName, aRJournal.PK, OrgHeaderSchema.Constants.Prefix, TestObjectCreator.LocalClient.PK);
			ScriptTestHelper.CreateMultiSubAccounts(TestObjectCreator, AccTransactionHeaderSubAccountSchema.Constants.TableName, aRJournal.PK, AccGroupsSchema.Constants.Prefix, salesGroup.PK);
			ScriptTestHelper.CreateMultiSubAccounts(TestObjectCreator, AccTransactionHeaderSubAccountSchema.Constants.TableName, aRJournal.PK, GlbStaffSchema.Constants.Prefix, staff.PK);
			ScriptTestHelper.CreateMultiSubAccounts(TestObjectCreator, AccTransactionHeaderSubAccountSchema.Constants.TableName, aRJournal.PK, GlbGroupSchema.Constants.Prefix, staffGroup.PK);
			Factory.Save();

			DataTable resultForSettlementGroup = RunScript(arInvoice.AH_PostDate, arInvoice.AH_PostDate);
			AssertEquals("Count of invoice should be 20", 19, resultForSettlementGroup.Rows.Count);

			var selectedRows = resultForSettlementGroup.Select(string.Format("GLAccount = 'GLHeader1'"));
			AssertEquals(4, selectedRows.Length);

			foreach (DataRow row in selectedRows)
			{
				switch ($"{row["Ledger"].ToString().Trim()}-{row["TransactionType"].ToString().Trim()}")
				{
					case "AR-INV":
						AssertEquals($"ORG: {TestObjectCreator.LocalClient.OH_Code}, SEG: {salesGroup.AR_Code}", row["MultiSubAccountTypeCode"].ToString());
						AssertEquals(TestObjectCreator.LocalClient.OH_Code, row["OrganisationSubAccount"].ToString());
						AssertEquals(salesGroup.AR_Code, row["SalesExpenseGroupsSubAccount"].ToString());
						AssertEquals("", row["StaffAndResourcesSubAccount"].ToString());
						AssertEquals("", row["StaffGroupSubAccount"].ToString());
						break;
					case "AP-INV":
						AssertEquals($"ORG: , SEG: {salesGroup.AR_Code}, STR: {staff.GS_Code}, SGP: {staffGroup.GG_Code}", row["MultiSubAccountTypeCode"].ToString());
						AssertEquals("", row["OrganisationSubAccount"].ToString());
						AssertEquals(salesGroup.AR_Code, row["SalesExpenseGroupsSubAccount"].ToString());
						AssertEquals(staff.GS_Code, row["StaffAndResourcesSubAccount"].ToString());
						AssertEquals(staffGroup.GG_Code, row["StaffGroupSubAccount"].ToString());
						break;
					case "AP-CRD":
						AssertEquals($"ORG: {TestObjectCreator.LocalClient.OH_Code}, SEG: {salesGroup.AR_Code}, SGP: {staffGroup.GG_Code}", row["MultiSubAccountTypeCode"].ToString());
						AssertEquals(TestObjectCreator.LocalClient.OH_Code, row["OrganisationSubAccount"].ToString());
						AssertEquals(salesGroup.AR_Code, row["SalesExpenseGroupsSubAccount"].ToString());
						AssertEquals("", row["StaffAndResourcesSubAccount"].ToString());
						AssertEquals(staffGroup.GG_Code, row["StaffGroupSubAccount"].ToString());
						break;
					case "AR-JNL":
						AssertEquals($"ORG: {TestObjectCreator.LocalClient.OH_Code}, SEG: {salesGroup.AR_Code}, STR: {staff.GS_Code}, SGP: {staffGroup.GG_Code}", row["MultiSubAccountTypeCode"].ToString());
						AssertEquals(TestObjectCreator.LocalClient.OH_Code, row["OrganisationSubAccount"].ToString());
						AssertEquals(salesGroup.AR_Code, row["SalesExpenseGroupsSubAccount"].ToString());
						AssertEquals(staff.GS_Code, row["StaffAndResourcesSubAccount"].ToString());
						AssertEquals(staffGroup.GG_Code, row["StaffGroupSubAccount"].ToString());
						break;
					default:
						Fail("Should not go here!");
						break;
				}
			}
		}

