		public void TestMultiSubAccountsWithFilter_APReceipt()
		{
			var apReceipt = TestObjectCreator.CreateAPReceipt(1M, 300M, ZDateTime.Now, ZDateTime.Now, TestObjectCreator.ABIGAS.PK, TestObjectCreator.AUDBankAccount.PK);
			AssertTransactionAreNotAllowedToEnterSubAccounts(apReceipt, MultiSubAccountCategory.WithoutSubAccount);
			AssertTransactionAreNotAllowedToEnterSubAccounts(apReceipt, MultiSubAccountCategory.SingleSubAccount);
			AssertTransactionAreNotAllowedToEnterSubAccounts(apReceipt, MultiSubAccountCategory.MultiSubAccount);
		}

		#region Implementation

		enum MultiSubAccountCategory
		{
			WithoutSubAccount,
			SingleSubAccount,
			MultiSubAccount
		}

		void AssertMultiSubAccountsWithFilter(Type transactionType, MultiSubAccountCategory accountType)
		{
			AccGLHeader glAccount = null;
			if (accountType == MultiSubAccountCategory.SingleSubAccount)
			{
				glAccount = TestObjectCreator.CreateGLHeaderWithSubAccount(OrgHeaderSchema.Constants.Prefix, false);
			}
			else if (accountType == MultiSubAccountCategory.MultiSubAccount)
			{
				glAccount = TestObjectCreator.CreateGLHeaderWithSubAccount(OrgHeaderSchema.Constants.Prefix, false);
				TestObjectCreator.CreateGLHeaderSubAccount(glAccount, GlbStaffSchema.Constants.Prefix, false);
			}
			else if (accountType == MultiSubAccountCategory.WithoutSubAccount)
			{
				glAccount = TestObjectCreator.CreateGLHeader();
			}
			AssertNotNull("Precondition: GL Account must be created", glAccount);

			var isGLHeaderHasMultiSubAccount = accountType == MultiSubAccountCategory.MultiSubAccount;
			var isGLAccountWithoutSubAccount = accountType == MultiSubAccountCategory.WithoutSubAccount;
			var organization = TestObjectCreator.LocalClient;

			AccTransactionHeader header = null;
			if (transactionType == typeof(APInvoice)
				|| transactionType == typeof(ARInvoice)
				|| transactionType == typeof(APCreditNote)
				|| transactionType == typeof(ARCreditNote)
				|| transactionType == typeof(APAdjustmentNote)
				|| transactionType == typeof(ARAdjustmentNote)
				|| transactionType == typeof(DirectPayment)
				|| transactionType == typeof(DirectReceipt)
				|| transactionType == typeof(GLJournal))
			{
				header = CreateHeaderWithLines();
			}
			else if (transactionType == typeof(APJournal)
				|| transactionType == typeof(ARJournal))
			{
				header = CreateHeader();
			}
			else
			{
				Fail("Unsupported transactionType: " + transactionType.Name);
			}
			header.AH_PostToGL = "Y";

			Factory.Save();

			var expectedMultiSubAccountTypeCode = isGLHeaderHasMultiSubAccount ? $"ORG: {TestObjectCreator.LocalClient.OH_Code}, STR: " : $"ORG: {TestObjectCreator.LocalClient.OH_Code}";

			#region has sub account

			var result = RunScript(header.AH_PostDate, header.AH_PostDate, subAccountType: "", subAccountPK: null, noSubAccount: "N");
			var filter = $"TransactionType = '{header.AH_TransactionType}' AND Ledger = '{header.AH_Ledger}' AND GLAccount = '{glAccount.AG_AccountNum}'";
			var selectedRows = result.Select(filter);
			AssertEquals("Result of default filter", 1, selectedRows.Length);
			AssertEquals("Default filter", isGLAccountWithoutSubAccount ? "" : expectedMultiSubAccountTypeCode, selectedRows[0]["MultiSubAccountTypeCode"].ToString());

			result = RunScript(header.AH_PostDate, header.AH_PostDate, subAccountType: Constants.SubAccountType.Organization, subAccountPK: null, noSubAccount: "N");
			selectedRows = result.Select(filter);
			if (isGLAccountWithoutSubAccount)
			{
				AssertEquals("Result of organization filter", 0, selectedRows.Length);
			}
			else
			{
				AssertEquals("Result of organization filter", 1, selectedRows.Length);
				AssertEquals("Organization filter", expectedMultiSubAccountTypeCode, selectedRows[0]["MultiSubAccountTypeCode"].ToString());
			}

			result = RunScript(header.AH_PostDate, header.AH_PostDate, subAccountType: Constants.SubAccountType.Organization, subAccountPK: organization.PK, noSubAccount: "N");
			selectedRows = result.Select(filter);
			if (isGLAccountWithoutSubAccount)
			{
				AssertEquals("Result of organization and sub account parent Id filter", 0, selectedRows.Length);
			}
			else
			{
				AssertEquals("Result of organization and sub account parent Id filters", 1, selectedRows.Length);
				AssertEquals("Organization and sub account parent Id filters", expectedMultiSubAccountTypeCode, selectedRows[0]["MultiSubAccountTypeCode"].ToString());
			}

			result = RunScript(header.AH_PostDate, header.AH_PostDate, subAccountType: Constants.SubAccountType.StaffAndResources, subAccountPK: null, noSubAccount: "N");
			selectedRows = result.Select(filter);
			if (isGLHeaderHasMultiSubAccount)
			{
				AssertEquals("Result of staff filter", 1, selectedRows.Length);
				AssertEquals("It matches GL Header when use staff filter", expectedMultiSubAccountTypeCode, selectedRows[0]["MultiSubAccountTypeCode"].ToString());
			}
			else
			{
				AssertEquals("Result of staff filter", 0, selectedRows.Length);
			}

			#endregion

			#region no Sub Account

			result = RunScript(header.AH_PostDate, header.AH_PostDate, subAccountType: "", subAccountPK: null, noSubAccount: "Y");
			selectedRows = result.Select(filter);
			if (isGLHeaderHasMultiSubAccount)
			{
				AssertEquals("Result of no sub account filter", 1, selectedRows.Length);
				AssertEquals("matched GL Header", expectedMultiSubAccountTypeCode, selectedRows[0]["MultiSubAccountTypeCode"].ToString());
			}
			else
			{
				AssertEquals("Result of no sub account filter", 0, selectedRows.Length);
			}

			result = RunScript(header.AH_PostDate, header.AH_PostDate, subAccountType: Constants.SubAccountType.Organization, subAccountPK: null, noSubAccount: "Y");
			selectedRows = result.Select(filter);
			AssertEquals("Result of organization and no sub account filters", 0, selectedRows.Length);

			result = RunScript(header.AH_PostDate, header.AH_PostDate, subAccountType: Constants.SubAccountType.Organization, subAccountPK: organization.PK, noSubAccount: "Y");
			selectedRows = result.Select(filter);
			AssertEquals("Result of organization, sub account parent Id and no sub account filters", 0, selectedRows.Length);

			result = RunScript(header.AH_PostDate, header.AH_PostDate, subAccountType: Constants.SubAccountType.StaffAndResources, subAccountPK: null, noSubAccount: "Y");
			selectedRows = result.Select(filter);
			if (isGLHeaderHasMultiSubAccount)
			{
				AssertEquals("Result of staff and no sub account filters", 1, selectedRows.Length);
				AssertEquals("matched GL Header", expectedMultiSubAccountTypeCode, selectedRows[0]["MultiSubAccountTypeCode"].ToString());
			}
			else
			{
				AssertEquals("Result of staff and no sub account filters", 0, selectedRows.Length);
			}

			AccTransactionHeader CreateHeader()
			{
				AccTransactionHeader transactionHeader = null;
				if (transactionType == typeof(APJournal))
				{
					transactionHeader = TestObjectCreator.CreateJournal<APJournal>(0m, ZDateTime.Today, TestObjectCreator.ABIGAS.PK);
				}
				else
				{
					transactionHeader = TestObjectCreator.CreateJournal<ARJournal>(0m, ZDateTime.Today, TestObjectCreator.ABIGAS.PK);
				}

				transactionHeader.AH_AG = glAccount.PK;

				if (!isGLAccountWithoutSubAccount)
				{
					ScriptTestHelper.CreateMultiSubAccounts(TestObjectCreator, AccTransactionHeaderSubAccountSchema.Constants.TableName, transactionHeader.PK, OrgHeaderSchema.Constants.Prefix, organization.PK);
				}

				return transactionHeader;
			}

			AccTransactionHeader CreateHeaderWithLines()
			{
				TransactionHeaderWithLines headerWithLines = null;
				if (transactionType == typeof(APInvoice) ||
					transactionType == typeof(ARInvoice) ||
					transactionType == typeof(APCreditNote) ||
					transactionType == typeof(ARCreditNote) ||
					transactionType == typeof(APAdjustmentNote) ||
					transactionType == typeof(ARAdjustmentNote))
				{
					headerWithLines = TestObjectCreator.CreateInvoice(transactionType);
				}
				else if (transactionType == typeof(DirectPayment))
				{
					headerWithLines = TestObjectCreator.CreateDirectPayment(ZDateTime.Today, 100M, 10m, 100M, 0M);
				}
				else if (transactionType == typeof(DirectReceipt))
				{
					headerWithLines = TestObjectCreator.CreateDirectReceipt(ZDateTime.Today, 100M, 10m, 100M, 0M);
				}
				else if (transactionType == typeof(GLJournal))
				{
					headerWithLines = TestObjectCreator.CreateGLJournal(TransactionTypes.GLStandardJournal, ZDateTime.Today, ZDateTime.Today, null);
				}

				headerWithLines.Lines.RemoveAndDeleteAll();
				var line = headerWithLines.Lines.AddNew();
				line.AL_AG = glAccount.PK;
				line.AL_ReverseToGL = "Y";

				if (!isGLAccountWithoutSubAccount)
				{
					ScriptTestHelper.CreateMultiSubAccounts(TestObjectCreator, AccTransactionLineSubAccountSchema.Constants.TableName, line.PK, OrgHeaderSchema.Constants.Prefix, organization.PK);
				}

				return headerWithLines;
			}

			#endregion
		}

		void AssertTransactionAreNotAllowedToEnterSubAccounts(TransactionHeader header, MultiSubAccountCategory accountType)
		{
			AccGLHeader glAccount = null;
			if (accountType == MultiSubAccountCategory.SingleSubAccount)
			{
				glAccount = TestObjectCreator.CreateGLHeaderWithSubAccount(OrgHeaderSchema.Constants.Prefix, false);
			}
			else if (accountType == MultiSubAccountCategory.MultiSubAccount)
			{
				glAccount = TestObjectCreator.CreateGLHeaderWithSubAccount(OrgHeaderSchema.Constants.Prefix, false);
				TestObjectCreator.CreateGLHeaderSubAccount(glAccount, GlbStaffSchema.Constants.Prefix, false);
			}
			else if (accountType == MultiSubAccountCategory.WithoutSubAccount)
			{
				glAccount = TestObjectCreator.CreateGLHeader();
			}
			AssertNotNull("Precondition: GL Account must be created", glAccount);

			var organization = TestObjectCreator.LocalClient;
			header.AH_PostToGL = "Y";
			TestObjectCreator.AUDBankAccount.AB_AG = glAccount.PK;
			Factory.Save();

			var result = RunScript(header.AH_PostDate, header.AH_PostDate);
			var filter = $"TransactionType = '{header.AH_TransactionType}' AND Ledger = '{header.AH_Ledger}' AND GLAccount = '{glAccount.AG_AccountNum}'";
			var selectedRows = result.Select(filter);
			AssertEquals("Result of default filter", 1, selectedRows.Length);
			AssertEquals("default filter", "", selectedRows[0]["MultiSubAccountTypeCode"].ToString());

			result = RunScript(header.AH_PostDate, header.AH_PostDate, subAccountType: Constants.SubAccountType.Organization, subAccountPK: null, noSubAccount: "N");
			selectedRows = result.Select(filter);
			AssertEquals("Result of organization filter", 0, selectedRows.Length);

			result = RunScript(header.AH_PostDate, header.AH_PostDate, subAccountType: Constants.SubAccountType.Organization, subAccountPK: organization.PK, noSubAccount: "N");
			selectedRows = result.Select(filter);
			AssertEquals("Result of organization and sub account parent Id filter", 0, selectedRows.Length);

			result = RunScript(header.AH_PostDate, header.AH_PostDate, subAccountType: Constants.SubAccountType.StaffGroup, subAccountPK: null, noSubAccount: "N");
			selectedRows = result.Select(filter);
			AssertEquals("Result of staff filter", 0, selectedRows.Length);

			result = RunScript(header.AH_PostDate, header.AH_PostDate, subAccountType: "", subAccountPK: null, noSubAccount: "Y");
			selectedRows = result.Select(filter);
			AssertEquals("Result of no sub account filter", 0, selectedRows.Length);
		}

