			void CreateMultipleSubAccounts(Journal journal, DependentTransactionLine dependentTransactionLine)
			{
				if (journal != null)
				{
					var subAccounts = journal.SubAccounts.Cast<JournalSubAccount>();
					SetParentId(subAccounts.FirstOrDefault(x => x.AHS_SubClassParentTableCode == OrgHeaderSchema.Constants.Prefix), TestObjectCreator.LocalClient.PK);
					SetParentId(subAccounts.FirstOrDefault(x => x.AHS_SubClassParentTableCode == AccGroupsSchema.Constants.Prefix), salesGroup.PK);
					SetParentId(subAccounts.FirstOrDefault(x => x.AHS_SubClassParentTableCode == GlbStaffSchema.Constants.Prefix), staff.PK);

					void SetParentId(JournalSubAccount subAccount, ZGuid parentId)
					{
						if (subAccount != null)
						{
							subAccount.AHS_SubClassParentId = parentId;
						}
					}
				}

				if (dependentTransactionLine != null)
				{
					var subAccounts = dependentTransactionLine.SubAccounts.Cast<TransactionLineSubAccount>();
					SetParentId(subAccounts.FirstOrDefault(x => x.AL1_SubClassParentTableCode == OrgHeaderSchema.Constants.Prefix), TestObjectCreator.LocalClient.PK);
					SetParentId(subAccounts.FirstOrDefault(x => x.AL1_SubClassParentTableCode == AccGroupsSchema.Constants.Prefix), salesGroup.PK);
					SetParentId(subAccounts.FirstOrDefault(x => x.AL1_SubClassParentTableCode == GlbStaffSchema.Constants.Prefix), staff.PK);

					void SetParentId(TransactionLineSubAccount subAccount, ZGuid parentId)
					{
						if (subAccount != null)
						{
							subAccount.AL1_SubClassParentId = parentId;
						}
					}
				}
			}

			void CreateGLHeaderSubAccounts(ZGuid additionalAGPK)
			{
				ScriptTestHelper.CreateMultiSubAccounts(TestObjectCreator, AccGLHeaderSubAccountSchema.Constants.TableName, additionalAGPK, OrgHeaderSchema.Constants.Prefix, ZGuid.Empty);
				ScriptTestHelper.CreateMultiSubAccounts(TestObjectCreator, AccGLHeaderSubAccountSchema.Constants.TableName, additionalAGPK, AccGroupsSchema.Constants.Prefix, ZGuid.Empty);
				ScriptTestHelper.CreateMultiSubAccounts(TestObjectCreator, AccGLHeaderSubAccountSchema.Constants.TableName, additionalAGPK, GlbStaffSchema.Constants.Prefix, ZGuid.Empty);
				ScriptTestHelper.CreateMultiSubAccounts(TestObjectCreator, AccGLHeaderSubAccountSchema.Constants.TableName, additionalAGPK, GlbGroupSchema.Constants.Prefix, ZGuid.Empty);
			}

			void AssertMatchResult(bool isMatch, string expectedGLAccountNumber = "", string expectedMultiSubAccountTypeCode = "")
			{
				if (isMatch)
				{
					AssertEquals("Result count", 1, dataRows.Length);
					AssertEquals(expectedGLAccountNumber, dataRows[0]["GLAccount"]);
					AssertEquals("Result MultiSubAccountTypeCode", expectedMultiSubAccountTypeCode, dataRows[0]["MultiSubAccountTypeCode"].ToString());
				}
				else
				{
					AssertEquals("Result count", 0, dataRows.Length);
				}
			}
		}

