			TestObjectCreator.InsertTransaction("EXX", "AR", dueDate3, true, TestObjectCreator.ABIGAS.PK, glAccount.PK);
			TestObjectCreator.InsertTransaction("OVP", "AR", dueDate4, true, TestObjectCreator.ABIGAS.PK, glAccount.PK);
			TestObjectCreator.InsertTransaction("DSC", "AR", dueDate5, true, TestObjectCreator.ABIGAS.PK, glAccount.PK);
			var arInvoice = TestObjectCreator.CreateInvoiceWithLine(typeof(ARInvoice), "ARINV1",
																	TestObjectCreator.AUD,
																	1M, 10M, 0M, 10M, 0M,
																	TestObjectCreator.ABIGAS,
																	glAccount.PK, dueDate6, true);

			var arCreditNote = TestObjectCreator.CreateARCreditNoteWithLine("ARCRD0001", TestObjectCreator.ABIGAS,
																	TestObjectCreator.AUD, 1m,
																	"AR Credit Note", null,
																	TestObjectCreator.CC1,
																	100m, dueDate7, true);

			TestObjectCreator.InsertTransaction("JNL", "AP", dueDate8, true, TestObjectCreator.ABIGAS.PK, glAccount.PK);
			TestObjectCreator.InsertTransaction("ADJ", "AP", dueDate9, true, TestObjectCreator.ABIGAS.PK, glAccount.PK);
			TestObjectCreator.InsertTransaction("EXX", "AP", dueDate10, true, TestObjectCreator.ABIGAS.PK, glAccount.PK);
			TestObjectCreator.InsertTransaction("OVP", "AP", dueDate11, true, TestObjectCreator.ABIGAS.PK, glAccount.PK);
			TestObjectCreator.InsertTransaction("DSC", "AP", dueDate12, true, TestObjectCreator.ABIGAS.PK, glAccount.PK);
			var apInvoice = TestObjectCreator.CreateInvoiceWithLine(typeof(APInvoice), "APINV1",
																	TestObjectCreator.AUD,
																	1M, 10M, 0M, 10M, 0M,
																	TestObjectCreator.ABIGAS,
																	glAccount.PK, dueDate13, true);

			var apCreditNote = TestObjectCreator.CreateAPCreditNoteWithLine("APCRD0001", TestObjectCreator.ABIGAS,
																	TestObjectCreator.AUD, 1m,
																	"AP Credit Note", null,
																	TestObjectCreator.CommentChargeCode,
																	100m, dueDate14, true);

			AccountingConfigurationRegistry.Instance.ARSuspenseControlAccount.SetValue(Guid.Empty, Guid.Empty, Guid.Empty, TestObjectCreator.CreateARSuspenseControlAccount().PK.ToGuid());
			AccountingConfigurationRegistry.Instance.APSuspenseControlAccount.SetValue(Guid.Empty, Guid.Empty, Guid.Empty, TestObjectCreator.CreateAPSuspenseControlAccount().PK.ToGuid());

			Factory.Save();

			var resultForSettlementGroup = RunScript(startDate, ZGuid.Empty, ZGuid.Empty);
			AssertEquals("Count of invoice", 26, resultForSettlementGroup.Rows.Count);
			foreach (DataRow row in resultForSettlementGroup.Rows)
			{
				var ledger = row["Ledger"].ToString().Trim();
				var transactionType = row["TransactionType"].ToString().Trim();

				var expectedDueDate = ZDate.Empty;
				if (ledger == "AR")
				{
					if (transactionType == "JNL")
					{
						expectedDueDate = dueDate1.Date;
					}
					if (transactionType == "ADJ")
					{
						expectedDueDate = dueDate2.Date;
					}
					if (transactionType == "EXX")
					{
						expectedDueDate = dueDate3.Date;
					}
					if (transactionType == "OVP")
					{
						expectedDueDate = dueDate4.Date;
					}
					if (transactionType == "DSC")
					{
						expectedDueDate = dueDate5.Date;
					}
					if (transactionType == "INV")
					{
						expectedDueDate = dueDate6.Date;
					}
					if (transactionType == "CRD")
					{
						expectedDueDate = dueDate7.Date;
					}
				}
				if (ledger == "AP")
				{
					if (transactionType == "JNL")
					{
						expectedDueDate = dueDate8.Date;
					}
					if (transactionType == "ADJ")
					{
						expectedDueDate = dueDate9.Date;
					}
					if (transactionType == "EXX")
					{
						expectedDueDate = dueDate10.Date;
					}
					if (transactionType == "OVP")
					{
						expectedDueDate = dueDate11.Date;
					}
					if (transactionType == "DSC")
					{
						expectedDueDate = dueDate12.Date;
					}
					if (transactionType == "INV")
					{
						expectedDueDate = dueDate13.Date;
					}
					if (transactionType == "CRD")
					{
						expectedDueDate = dueDate14.Date;
					}
				}

				if (expectedDueDate.IsEmpty)
				{
					AssertEquals($"{ledger} {transactionType} DueDate", DBNull.Value, row["DueDate"]);
				}
				else
				{
					AssertEquals($"{ledger} {transactionType} DueDate", expectedDueDate.ToDateTime(), ((DateTime)row["DueDate"]).Date);
				}
			}
		}

		[TestDate(2018, 11, 09, 12, 00, 00)]
		public void TestOsExCreditAndOsExDebitAreTakenFromOSAmountWhenGSTAmountIsZero()
		{
			var originalGC_IsReciprocal = GlbCompany.CurrentCompany.GC_IsReciprocal;
			try
			{
				GlbCompany.CurrentCompany.GC_IsReciprocal = true;
				GlbCompany.CurrentCompany.Factory.Save();

				var directReceipt = TestObjectCreator.CreateDirectReceipt(ZDateTime.Today, 211834M, 0M, 10000M, 0M, TestObjectCreator.USDBankAccount.PK, 0.000665);
				var directPayment = TestObjectCreator.CreateDirectPayment(ZDateTime.Today, 211834M, 0M, 10000M, 0M, TestObjectCreator.USDBankAccount.PK, 0.000666);
				directReceipt.AH_PostToGL = "Y";
				directPayment.AH_PostToGL = "Y";
				Factory.Save();

				var dt = RunScript(directReceipt.AH_PostDate, directReceipt.AH_PostDate);
				AssertEquals("Totoal Number of Rows = ((2 DRC Lines + 2 DPY Lines) x (1 dr/cr + 1 dr/cr Tax line) + 1dr + 1cr )", 10, dt.Rows.Count);

				var sortedRows = dt.Rows.OfType<DataRow>()
					.Select(r => new {
						Row = r,
						OrderingInfo = new { tranType = Convert.ToString(r["TransactionType"]), Side = ConvertToDecimal(r["OsExTaxDebit"]) != 0 ? 1 : 0, Amount = ConvertToDecimal(r["OsExTaxDebit"]) != 0 ? ConvertToDecimal(r["OsExTaxDebit"]) : ConvertToDecimal(r["OsExTaxCredit"]) }
					})
					.OrderBy(ro => ro.OrderingInfo.tranType)
					.ThenBy(ro => ro.OrderingInfo.Side)
					.ThenByDescending(ro => ro.OrderingInfo.Amount)
					.Select(ro => ro.Row)
					.ToArray();

				AssertEachRow(sortedRows[0], 221834M, 0M);
				AssertEachRow(sortedRows[1], 0M, 0M);
				AssertEachRow(sortedRows[2], 0M, 0M);
				AssertEachRow(sortedRows[3], 0M, 211834M);
				AssertEachRow(sortedRows[4], 0M, 10000M);

				AssertEachRow(sortedRows[5], 211834M, 0M);
				AssertEachRow(sortedRows[6], 10000M, 0M);
				AssertEachRow(sortedRows[7], 0M, 0M);
				AssertEachRow(sortedRows[8], 0M, 0M);
				AssertEachRow(sortedRows[9], 0M, 221834M);
			}
			finally
			{
				GlbCompany.CurrentCompany.GC_IsReciprocal = originalGC_IsReciprocal;
			}

			decimal? ConvertToDecimal(object cellValue)
			{
				return cellValue == DBNull.Value ? 0M : (decimal?)cellValue;
			}

			void AssertEachRow(DataRow row, decimal expectedOsExTaxCreditAmount, decimal expectedOsExTaxDebitAmount)
			{
				AssertEquals(expectedOsExTaxCreditAmount, ConvertToDecimal(row["OsExTaxCredit"]));
				AssertEquals(expectedOsExTaxDebitAmount, ConvertToDecimal(row["OsExTaxDebit"]));
				AssertEquals(ConvertToDecimal(row["OsCredit"]), ConvertToDecimal(row["OsExTaxCredit"]));
				AssertEquals(ConvertToDecimal(row["OsDebit"]), ConvertToDecimal(row["OsExTaxDebit"]));
			}
		}

