		[SuspendCriticalValidation]
		[TestDate(2020, 01, 20)]
		public void TestOtherTax_GLTransactionsWithMultipleTaxSuperTypes()
		{
			setupCommonData();
			var currentCompany = GlbCompany.CurrentCompany;
			var nonCurrentCompany = TestObjectCreator.CreateNewCompany("NON");
			var branch1 = TestObjectCreator.CreateBranch("AT1", currentCompany);
			var branch2 = TestObjectCreator.CreateBranch("BT1", currentCompany);
			var department1 = TestObjectCreator.CreateDepartment("X11");
			var department2 = TestObjectCreator.CreateDepartment("X12");

			var config_AR_SalesTax = TaxFrameworkTestHelper.CreateTaxConfiguration(branch1, LedgerTypes.AccountsReceivable);
			config_AR_SalesTax.ETC_TaxRecordCreationTrigger = TaxRealisationMethods.PostDate.Code;
			config_AR_SalesTax.ETC_TaxRealisationMethod = TaxRealisationMethods.PostDate.Code;
			config_AR_SalesTax.ETC_AG_TaxControlAccount = taxLiabilityControlAccount.PK;
			config_AR_SalesTax.ETC_AG_TaxExpenseAccount = negativeRevenueControlAccount.PK;

			var config_AP_PerceptionsTax = TaxFrameworkTestHelper.CreateTaxConfiguration(LedgerTypes.AccountsPayable);
			config_AP_PerceptionsTax.ETC_TaxRecordCreationTrigger = TaxRealisationMethods.PostDate.Code;
			config_AP_PerceptionsTax.ETC_TaxRealisationMethod = TaxRealisationMethods.MatchDate.Code;
			config_AP_PerceptionsTax.ETC_AG_LedgerControlAccount = apAccount.PK;
			config_AP_PerceptionsTax.ETC_AG_TaxControlAccount = taxAssetControlAccount.PK;
			config_AP_PerceptionsTax.ETC_AG_TaxPendingControlAccount = taxPendingControlAccount.PK;

			var postDate = ZDate.Today;
			var matchDate = ZDate.Today.AddDays(45);

			var postPeriod = PeriodCalculator.GetPeriodFromDate(postDate);
			var matchPeriod = PeriodCalculator.GetPeriodFromDate(matchDate);

			var taxTransaction1 = TaxFrameworkTestHelper.CreateTaxTransaction(new CreateTaxTransactionParameters { TaxConfiguration = config_AP_PerceptionsTax, Branch = branch1, Department = department1, PostDate = postDate, LocalTaxAmount = -10M, OsTaxAmount = -10M, LocalTaxBaseAmount = -100M, OsTaxBaseAmount = -100M, DoesNotCreateGLMovemetsOnSaving = true });
			taxTransaction1.ATT_RealisationDate = postDate;
			TaxFrameworkTestHelper.CreateAccTaxGLMovement(taxTransaction1.PK, taxPendingControlAccount.PK, apAccount.PK, 10M, postPeriod, type: TaxGLMovementTypeList.Pending.Code);
			TaxFrameworkTestHelper.CreateAccTaxGLMovement(taxTransaction1.PK, taxAssetControlAccount.PK, taxPendingControlAccount.PK, 10M, postPeriod, type: TaxGLMovementTypeList.Realised.Code);
			taxTransaction1.ATT_GC = nonCurrentCompany.PK;

			var taxTransaction2 = TaxFrameworkTestHelper.CreateTaxTransaction(new CreateTaxTransactionParameters { TaxConfiguration = config_AP_PerceptionsTax, Branch = branch1, Department = department1, PostDate = postDate, LocalTaxAmount = 20M, OsTaxAmount = 20M, LocalTaxBaseAmount = -100M, OsTaxBaseAmount = -100M, RealisationDate = matchDate, DoesNotCreateGLMovemetsOnSaving = true });
			TaxFrameworkTestHelper.CreateAccTaxGLMovement(taxTransaction2.PK, apAccount.PK, taxPendingControlAccount.PK, 20M, postPeriod, type: TaxGLMovementTypeList.Pending.Code);
			TaxFrameworkTestHelper.CreateAccTaxGLMovement(taxTransaction2.PK, taxPendingControlAccount.PK, taxAssetControlAccount.PK, 20M, matchPeriod, type: TaxGLMovementTypeList.Realised.Code);
			taxTransaction2.ATT_GC = nonCurrentCompany.PK;

			var taxTransaction3 = TaxFrameworkTestHelper.CreateTaxTransaction(new CreateTaxTransactionParameters { TaxConfiguration = config_AR_SalesTax, Branch = branch2, Department = department2, PostDate = postDate, LocalTaxAmount = -30M, OsTaxAmount = -30M, LocalTaxBaseAmount = -100M, OsTaxBaseAmount = -100M, DoesNotCreateGLMovemetsOnSaving = true });
			TaxFrameworkTestHelper.CreateAccTaxGLMovement(taxTransaction3.PK, negativeRevenueControlAccount.PK, taxLiabilityControlAccount.PK, 30M, postPeriod);
			taxTransaction3.ATT_GC = nonCurrentCompany.PK;

			Factory.Save();
			RandomSetupFix();

			Db.Connection.ExecuteNonQuery(string.Format("EXEC TakeUpSubledgers '{0}', 'TST'", currentCompany.PK));
			var dataTable = GetAccGLAggregateDataTable();
			Assert("No transactions found for take up", dataTable.Rows.Count == 0);

			taxTransaction1.ATT_GC = currentCompany.PK;
			taxTransaction2.ATT_GC = currentCompany.PK;
			taxTransaction3.ATT_GC = currentCompany.PK;
			Factory.Save();

			Db.Connection.ExecuteNonQuery(string.Format("EXEC TakeUpSubledgers '{0}', 'TST'", currentCompany.PK));

			CombineAssertions(() =>
			{
				dataTable = GetAccGLAggregateDataTable();
				Assert(dataTable.Rows.Count == 7);
				var glAggregates = dataTable.Select($"AA_AG='{apAccount.PK}' and AA_Period='{postPeriod}'");
				AssertGLAggregate(10M, currentCompany, branch1, department1, apAccount, postPeriod);

				glAggregates = dataTable.Select($"AA_AG='{taxAssetControlAccount.PK}' and AA_Period='{postPeriod}'");
				AssertGLAggregate(10M, currentCompany, branch1, department1, taxAssetControlAccount, postPeriod);

				glAggregates = dataTable.Select($"AA_AG='{taxAssetControlAccount.PK}' and AA_Period='{matchPeriod}'");
				AssertGLAggregate(-20M, currentCompany, branch1, department1, taxAssetControlAccount, matchPeriod);

				glAggregates = dataTable.Select($"AA_AG='{taxPendingControlAccount.PK}' and AA_Period='{postPeriod}'");
				AssertGLAggregate(-20M, currentCompany, branch1, department1, taxPendingControlAccount, postPeriod);

				glAggregates = dataTable.Select($"AA_AG='{taxPendingControlAccount.PK}' and AA_Period='{matchPeriod}'");
				AssertGLAggregate(20M, currentCompany, branch1, department1, taxPendingControlAccount, matchPeriod);

				glAggregates = dataTable.Select($"AA_AG='{taxLiabilityControlAccount.PK}' and AA_Period='{postPeriod}'");
				AssertGLAggregate(-30M, currentCompany, branch2, department2, taxLiabilityControlAccount, postPeriod);

				glAggregates = dataTable.Select($"AA_AG='{negativeRevenueControlAccount.PK}' and AA_Period='{postPeriod}'");
				AssertGLAggregate(30M, currentCompany, branch2, department2, negativeRevenueControlAccount, postPeriod);

				void AssertGLAggregate(ZDecimal expectedAmount, GlbCompany expectedCompany, GlbBranch expectedBranch, GlbDepartment expectedDepartment, AccGLHeader glAccount, int period)
				{
					AssertEquals("One record should be found", 1, glAggregates.Length);
					var actualRow = glAggregates[0];
					AssertEquals($"{glAccount.AG_AccountNum} in {period}: amount", expectedAmount, Decimal.Parse(actualRow["AA_Amount"].ToString()));
					AssertEquals($"{glAccount.AG_AccountNum} in {period}: company", expectedCompany.PK, actualRow["AA_GC"]);
					AssertEquals($"{glAccount.AG_AccountNum} in {period}: branch", expectedBranch.PK, actualRow["AA_GB"]);
					AssertEquals($"{glAccount.AG_AccountNum} in {period}: department", expectedDepartment.PK, actualRow["AA_GE"]);
				}
			});
		}

		[SuspendCriticalValidation]
		[TestDate(2020, 01, 20)]
		public void TestOtherTax_GLTransactionsWithNetZeroTax()
		{
			setupCommonData();

			var currentCompany = GlbCompany.CurrentCompany;
			var branch = GlbBranch.CurrentBranch;
			var department = GlbDepartment.CurrentDepartment;

			var config = TaxFrameworkTestHelper.CreateTaxConfiguration(LedgerTypes.AccountsPayable);
			config.ETC_TaxRecordCreationTrigger = TaxRealisationMethods.PostDate.Code;
			config.ETC_TaxRealisationMethod = TaxRealisationMethods.MatchDate.Code;
			config.ETC_AG_LedgerControlAccount = apAccount.PK;
			config.ETC_AG_TaxControlAccount = taxAssetControlAccount.PK;
			config.ETC_AG_TaxPendingControlAccount = taxPendingControlAccount.PK;

			var postDate = ZDate.Today;
			var postPeriod = PeriodCalculator.GetPeriodFromDate(postDate);

			var taxTransaction1 = TaxFrameworkTestHelper.CreateTaxTransaction(new CreateTaxTransactionParameters { TaxConfiguration = config, Branch = branch, Department = department, PostDate = postDate, LocalTaxAmount = -10M, OsTaxAmount = -10M, LocalTaxBaseAmount = -100M, OsTaxBaseAmount = -100M, DoesNotCreateGLMovemetsOnSaving = true });
			TaxFrameworkTestHelper.CreateAccTaxGLMovement(taxTransaction1.PK, taxPendingControlAccount.PK, apAccount.PK, 10M, postPeriod);

			var taxTransaction2 = TaxFrameworkTestHelper.CreateTaxTransaction(new CreateTaxTransactionParameters { TaxConfiguration = config, Branch = branch, Department = department, PostDate = postDate, LocalTaxAmount = 10M, OsTaxAmount = 10M, LocalTaxBaseAmount = -100M, OsTaxBaseAmount = -100M, DoesNotCreateGLMovemetsOnSaving = true });
			TaxFrameworkTestHelper.CreateAccTaxGLMovement(taxTransaction2.PK, apAccount.PK, taxPendingControlAccount.PK, 10M, postPeriod);

			Factory.Save();
			RandomSetupFix();

			Db.Connection.ExecuteNonQuery(string.Format("EXEC TakeUpSubledgers '{0}', 'TST'", currentCompany.PK));
			var dataTable = GetAccGLAggregateDataTable();
			Assert("No transactions found for take up as the invoice and credit note cancels each other out", dataTable.Rows.Count == 0);
		}

		[TestDate(2022, 11, 15)]
		public void TestPBWJournalIsExcluded()
		{
			var apJournal = CreateNonPBWJournal();
			var apPBWJournal = CreateNonPBWJournal();
			apPBWJournal.AH_TransactionCategory = TransactionCategory.Codes.PaymentBasisWithholding;
			Factory.Save();

			var resultTable = RunScript(apPBWJournal.AH_PostDate, apPBWJournal.AH_PostDate);

			AssertDataTableAllRows("",
				resultTable,
				new[] { "PK", "TransactionDesc" },
				new object[][]
				{
							new object[] { DBNull.Value, "AP Control Account" },
							new object[] { apJournal.PK, "AP JOURNAL" },
				}
			);

			APJournal CreateNonPBWJournal()
			{
				var journal = TestObjectCreator.CreateJournal<APJournal>(100, ZDateTime.Now, TestObjectCreator.ABIGAS.PK);
				SetTransactionHeaderDetails(journal);

				AssertNotEquals("Precondition: AH_TransactionCategory", TransactionCategory.Codes.PaymentBasisWithholding, journal.AH_TransactionCategory);

				return journal;
			}
		}

