		void DuplicateGenExportBatchSequenceRecords()
		{
			var sql = @"
SELECT
	newid(),
	REPLACE(XB_Type,'E','Z'),
	case 
		when XB_Type='ENP' then 'GPS'
		when XB_Type='ENR' then 'GRV'
		when XB_Type='ERP' then 'LEX'
		when XB_Type='ERR' then 'LRX'
	end
	XB_BatchNumber,
	XB_Sequence,
	XB_ParentTableCode,
	XB_ParentID
FROM dbo.GenExportBatchSequence 
WHERE XB_Type IN ('ENP','ENR','ERP','ERR')";

			using (var cmd = Db.Connection.Command(sql))
			{
				cmd.ExecuteNonQuery();
			}
		}

		DataTable RunScript(ZInt startPeriod, ZInt endPeriod, ZGuid companyPK, ZGuid startGLAccount, ZGuid endGLAccount, ZGuid branchPK = default, ZGuid departmentPK = default)
		{
			string sql = $@"
EXEC GLTransactionsSP 
@CompanyPK				= '{companyPK}',
@StartPeriod			= {startPeriod},
@EndPeriod				= {endPeriod},
@StartDate				= NULL,
@EndDate				= NULL,
@StartGLAccountPK		= '{startGLAccount}',
@EndGLAccountPK			= '{endGLAccount}',
@BranchPK				= {(!branchPK.IsDefault ? string.Format("'{0}'", branchPK) : "NULL")},
@DepartmentPK			= {(!departmentPK.IsDefault ? string.Format("'{0}'", departmentPK) : "NULL")},
@DisplayDescription		= 'HDR',
@TransactionCategory	= NULL,
@BatchNumberToGet		= NULL,
@BatchNumberToSet		= NULL,
@IncludeZeroBalance		= '';
";

			return DataUtils.GetDataTableFromQuery(Db.Connection, sql);
		}

		DataTable RunScript(ZDateTime startDate, ZDateTime endDate, ZGuid? startGLAccountPK = null, ZGuid? endGLAccountPK = null, ZDateTime? highWaterMark = null, int? batchNumberToSet = null, bool isExportingBatch = false, string subAccountType = "", ZGuid? subAccountPK = null, string noSubAccount = "N")
		{
			string sql = $@"
			EXEC GLTransactionsSP
			@CompanyPK				= '{GlbCompany.CurrentCompany.PK}',
			@StartPeriod			= NULL,
			@EndPeriod				= NULL,
			@StartDate				= '{startDate.AddDays(-1).EndOfDay().AddSeconds(1).ToISO8601String()}',
			@EndDate				= '{endDate.EndOfDay().AddSeconds(1).ToISO8601String()}',
			@StartGLAccountPK		= {(startGLAccountPK.HasValue ? string.Format("'{0}'", startGLAccountPK.ToString()) : "NULL")},
			@EndGLAccountPK			= {(endGLAccountPK.HasValue ? string.Format("'{0}'", endGLAccountPK.ToString()) : "NULL")},
			@BranchPK				= NULL,
			@DepartmentPK			= NULL,
			@DisplayDescription		= '',
			@TransactionCategory	= '',
			@BatchNumberToGet		= NULL,
			@BatchNumberToSet		= {(batchNumberToSet.HasValue ? batchNumberToSet.ToString() : "NULL")},
			@IncludeZeroBalance		= '',
			@IsExportingBatch		= '{(isExportingBatch ? "Y" : "N")}', 
			@HighWaterMark			= {(highWaterMark.HasValue ? string.Format("'{0}'", highWaterMark.Value.ToISO8601String()) : "NULL")},
			@SubAccountType			= '{subAccountType}',
			@SubAccountPK			= {(subAccountPK.HasValue ? string.Format("'{0}'", subAccountPK.ToString()) : "NULL")},
			@NoSubAccount			= '{noSubAccount}'
			";

			return DataUtils.GetDataTableFromQuery(Db.Connection, sql);
		}

		DataTable RunScript(ZDateTime startDate, ZGuid startLocalAccount, ZGuid endLocalAccount)
		{
			string sql = string.Format(@"
							EXEC GLTransactionsSP
							'{0}',	--@Company
							NULL,
							NULL,
							'{1}',	--@FromDate
							'{2}',	--@ToDate
							NULL,	--@StartGLAccountPK
							NULL,	--@EndGLAccountPK
							'{3}',	--@BranchPK
							'{4}',	--@DepartmentPK
							'', '', null, null, ''",
						GlbCompany.CurrentCompany.PK,
						startDate.AddDays(-100).ToISO8601String(),
						startDate.AddDays(100).ToISO8601String(),
						GlbBranch.CurrentBranch.PK,
						GlbDepartment.CurrentDepartment.PK
						);
			if (!startLocalAccount.IsEmpty || !endLocalAccount.IsEmpty)
			{
				sql = string.Format(@"
							EXEC GLTransactionsSP
							'{0}',	--@Company
							NULL,
							NULL,
							'{1}',	--@FromDate
							'{2}',	--@ToDate
							NULL,	--@StartGLAccountPK
							NULL,	--@EndGLAccountPK
							'{3}',	--@BranchPK
							'{4}',	--@DepartmentPK
							'', '', null, null, '',
							'N',
							null,
							'{5}',
							'{6}'",
						GlbCompany.CurrentCompany.PK,
						startDate.AddDays(-100).ToISO8601String(),
						startDate.AddDays(100).ToISO8601String(),
						GlbBranch.CurrentBranch.PK,
						GlbDepartment.CurrentDepartment.PK,
						startLocalAccount,
						endLocalAccount);
			}
			return DataUtils.GetDataTableFromQuery(Db.Connection, sql);
		}

		DataTable GetAccGLAggregateDataTable()
		{
			string sql = "SELECT AA_AG, AA_Period, AA_Amount, AA_GC, AA_GB, AA_GE, AA_TransactionCategory FROM dbo.AccGLAggregate";

			return DataUtils.GetDataTableFromQuery(Db.Connection, sql);
		}

